  INTO v_mother_ethnicity, v_mother_religion, v_mother_household_id
  FROM public.resident
 WHERE resident_id = v_mother_id AND woreda_id = NEW.woreda_id;
IF v_mother_id IS NOT NULL AND NOT FOUND THEN
  RAISE EXCEPTION 'mother_resident_id does not belong to this woreda' USING ERRCODE = 'check_violation';
END IF;

